#!/usr/bin/env node
/**
 * Bundles foliate-js into a self-contained IIFE and generates foliateBundle.ts.
 *
 * Usage: npm run build:foliate
 *
 * What it does:
 *   1. Runs esbuild on node_modules/foliate-js/view.js with --bundle --format=iife.
 *      - Excludes pdf.js, tts.js, search.js (not needed for EPUB reading).
 *      - All other dynamic imports (epub.js, paginator.js, vendor/zip.js, etc.) are inlined.
 *      - useWebWorkers is already set to false in view.js — no Worker is spawned at runtime.
 *   2. Sanitises the output (replaces </script> to avoid breaking the HTML <script> tag).
 *   3. Writes the bundle content as a TS string constant to src/features/reader-foliate/foliateBundle.ts.
 *
 * The generated foliateBundle.ts is committed to git.
 * Re-run this script only when updating the foliate-js dependency.
 */

const { execSync } = require('child_process');
const fs = require('fs');
const path = require('path');

const ROOT = path.resolve(__dirname, '..');
const BUNDLE_OUT = path.join(ROOT, 'assets', 'foliate', 'foliate-bundle.js');
const TS_OUT = path.join(ROOT, 'src', 'features', 'reader-foliate', 'foliateBundle.ts');

fs.mkdirSync(path.dirname(BUNDLE_OUT), { recursive: true });
fs.mkdirSync(path.dirname(TS_OUT), { recursive: true });

console.log('Building foliate-js IIFE bundle...');
execSync(
	[
		'npx esbuild',
		'node_modules/foliate-js/view.js',
		'--bundle',
		'--format=iife',
		'--global-name=__foliate',
		'--external:./pdf.js',
		'--external:./tts.js',
		'--external:./search.js',
		`--outfile=${BUNDLE_OUT}`,
	].join(' '),
	{ stdio: 'inherit', cwd: ROOT },
);

const raw = fs.readFileSync(BUNDLE_OUT, 'utf8');

// Prevent the bundle from breaking an HTML <script> block.
const sanitised = raw.replace(/<\/script>/gi, '<\\/script>');

// JSON.stringify produces a valid JS/TS string literal: all newlines, quotes,
// and special characters are properly escaped.
const tsContent =
	'// Generated by scripts/build-foliate-bundle.js — do not edit manually.\n' +
	'// Run: npm run build:foliate\n' +
	`export const foliateBundle: string = ${JSON.stringify(sanitised)};\n`;

fs.writeFileSync(TS_OUT, tsContent, 'utf8');

const kb = Math.round(raw.length / 1024);
console.log(`✓ foliateBundle.ts written (${kb} KB)`);
